def get_annexe_c_mapping(third_groups):
    """Return the Annexe C slot mapping for the eight qualified third-place groups.

    Args:
        third_groups: iterable of group letters or third labels, e.g.
            ["E", "F", "G", "H", "I", "J", "K", "L"]
            or ["3E", "3F", "3G", "3H", "3I", "3J", "3K", "3L"]

    Returns:
        dict like {"1A": "3E", "1B": "3J", ...}

    Raises:
        ValueError: if the input does not contain exactly 8 distinct groups A-L.
        KeyError: if the combination is not present in Annexe C.
    """
    groups = []
    for item in third_groups:
        s = str(item).strip().upper()
        if s.startswith("3"):
            s = s[1:]
        groups.append(s)

    key = "".join(sorted(set(groups)))
    if len(key) != 8 or any(g not in "ABCDEFGHIJKL" for g in key):
        raise ValueError(f"Expected exactly 8 distinct groups A-L, got: {third_groups!r}")

    return ANNEXE_C_BY_THIRD_GROUPS[key]


def validate_annexe_c():
    """Internal integrity check. Returns True or raises AssertionError."""
    assert len(ANNEXE_C_BY_OPTION) == 495
    assert len(ANNEXE_C_BY_THIRD_GROUPS) == 495
    allowed = {
        "1A": set("CEFHI"),
        "1B": set("EFGIJ"),
        "1D": set("BEFIJ"),
        "1E": set("ABCDF"),
        "1G": set("AEHIJ"),
        "1I": set("CDFGH"),
        "1K": set("DEIJL"),
        "1L": set("EHIJK"),
    }

    for option, mapping in ANNEXE_C_BY_OPTION.items():
        assert set(mapping) == set(SLOTS), (option, mapping)
        assigned_groups = [third[1] for third in mapping.values()]
        assert len(assigned_groups) == 8
        assert len(set(assigned_groups)) == 8, (option, mapping)

        for slot, third in mapping.items():
            assert third.startswith("3") and len(third) == 2
            group = third[1]
            assert group in allowed[slot], (option, slot, third)
            assert group != slot[1], (option, slot, third)

    return True


if __name__ == "__main__":
    validate_annexe_c()
    print("OK: Annexe C has 495 valid combinations.")
